      if (batch_value->num_rows() == 0) continue;

      std::shared_ptr<arrow::RecordBatch> filtered_batch;
      auto as =
          FilterRecordBatch(batch_value, filter, row_id_offset, &filtered_batch,
                            delete_row_id_bitmap, min_doc_id, max_doc_id);
      if (!as.ok()) {
